#pragma once

struct glyph_t
{
	uint16_t cp;         // code-point
	int8_t x, y;         // draw offset
	uint8_t advance;     // advance
	uint8_t kern_n;      // kerning pairs
	uint16_t kern_idx;   // kerning data index
	uint8_t w, h;        // size
	const uint8_t* data; // data pointer
};
struct kern_t
{
	uint16_t cp; // code-point
	int8_t k;    // kerning
};
struct font_t
{
	uint16_t baseline;
	uint16_t glyph_count;
	uint16_t bpp;
	const kern_t* kern;
	const glyph_t* glyph;
};

